    C=[[0]*(E+1) for _ in range(E+1)]
    # comb for needed d up to E, k up to N maybe
    for d in range(E+1):
        C[d][0]=1
        for k in range(1,min(d,N)+1):
            C[d][k]=comb(d,k)%P
    # transitions per a,b: list (shift, coef)
    T={}
    for a in range(1,N):
        for b in range(1,N-a+1):
            lst=[]
            intern=b*(b-1)//2
            for j in range(b+1):
                lst.append((a*(b-j)+intern, (-1 if j&1 else 1)*comb(b,j)%P))
            T[a,b]=lst
    dp={(1,1,1):[1]}
    ans=[0]*(E+1)
    for depth in range(N):
        nd={}
        odd = ((depth+1)&1)==1
        for (a,t,e),poly in dp.items():
            if t==N:
                if e==N//2:
                    for i,v in enumerate(poly):
                        if v: ans[i]=(ans[i]+v)%P
                continue
            rem=N-t
            for b in range(1,rem+1):
