def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m = data[0], data[1]
    parent = [x - 1 for x in data[2:2 + n]]

    indegree = [0] * n
    for v in parent:
        indegree[v] += 1

    queue = deque(i for i in range(n) if indegree[i] == 0)
    order = []
    while queue:
        v = queue.popleft()
        order.append(v)
        to = parent[v]
        indegree[to] -= 1
        if indegree[to] == 0:
            queue.append(to)

    products = [None] * n

    for v in order:
        poly = products[v]
        if poly is None:
            poly = list(range(1, m + 1))
        else:
            products[v] = None
            total = 0
            for i in range(m):
                total += poly[i]
                if total >= MOD:
                    total -= MOD
                poly[i] = total

        to = parent[v]
        current = products[to]
        if current is None:
            products[to] = poly
        else:
            for i in range(m):
                current[i] = current[i] * poly[i] % MOD

    answer = 1
    visited = [False] * n

    for start in range(n):
        if indegree[start] == 0 or visited[start]:
            continue

        component = None
        v = start
        while not visited[v]:
            visited[v] = True
            poly = products[v]
            if poly is None:
                if component is None:
                    component = [1] * m
            elif component is None:
                component = poly
            else:
                for i in range(m):
                    component[i] = component[i] * poly[i] % MOD
            v = parent[v]

        answer = answer * (sum(component) % MOD) % MOD

    print(answer)


if __name__ == "__main__":
    main()

import sys


def main():
    data = list(map(int, sys.stdin.buffer.read().split()))
    n, m, a, b = data[:4]
    intervals = [(data[i], data[i + 1]) for i in range(4, 4 + 2 * m, 2)]

    full = (1 << b) - 1
    relevant = 0
    for i in range(a - 1, b):
        relevant |= 1 << i

    def valid_step(mask):
        return ((mask << 1) & full) | (1 if mask & relevant else 0)

    def advance_valid(mask, length):
        if length <= 0 or mask == 0:
            return mask

        if a == b:
            shift = length % b
            if shift == 0:
                return mask
            return ((mask << shift) & full) | (mask >> (b - shift))

        if mask == full:
            return full

        seen = {}
        done = 0
        while length > 0:
            if mask == 0 or mask == full:
                return mask
            if mask in seen:
                cycle = done - seen[mask]
                length %= cycle
                for _ in range(length):
                    mask = valid_step(mask)
                return mask
            seen[mask] = done
            mask = valid_step(mask)
            done += 1
            length -= 1
        return mask

    def advance_bad(mask, length):
        if length >= b:
            return 0
        return (mask << length) & full

    mask = 1
    current = 1

    for left, right in intervals:
        mask = advance_valid(mask, left - current - 1)
        mask = advance_bad(mask, right - left + 1)
        current = right
        if mask == 0:
            break

    if mask:
        mask = advance_valid(mask, n - current)

    print("Yes" if mask & 1 else "No")


if __name__ == "__main__":
    main()

import sys
from math import comb


def main():
    n, mod = map(int, sys.stdin.buffer.read().split())
    max_edges = n * (n - 1) // 2
    half = n // 2

    choose = [[0] * (max_edges + 1) for _ in range(max_edges + 1)]
    for d in range(max_edges + 1):
        choose[d][0] = 1
        for k in range(1, d + 1):
            choose[d][k] = comb(d, k) % mod

    transitions = {}
    for previous in range(1, n):
        for new in range(1, n - previous + 1):
            inside = new * (new - 1) // 2
            terms = []
            for omitted in range(new + 1):
                shift = previous * (new - omitted) + inside
                coefficient = comb(new, omitted) % mod
                if omitted & 1:
                    coefficient = (-coefficient) % mod
                terms.append((shift, coefficient))
            transitions[previous, new] = terms

    dp = {(1, 1, 1): [1]}
    binomial_answer = [0] * (max_edges + 1)

    for depth in range(n):
        next_dp = {}
        odd_layer = ((depth + 1) & 1) == 1

        for (previous, vertices, even_count), poly in dp.items():
            if vertices == n:
                if even_count == half:
                    for i, value in enumerate(poly):
                        if value:
                            binomial_answer[i] = (binomial_answer[i] + value) % mod
                continue

            remaining = n - vertices
            for new in range(1, remaining + 1):
                if odd_layer:
                    new_even = even_count
                    new_odd = vertices - even_count + new
                else:
                    new_even = even_count + new
                    new_odd = vertices - even_count

                if new_even > half or new_odd > half:
                    continue

                capacity = (vertices + new) * (vertices + new - 1) // 2
                new_poly = [0] * (capacity + 1)
                length = len(poly)
                label_choices = comb(remaining, new) % mod

                for shift, coefficient in transitions[previous, new]:
                    factor = coefficient * label_choices % mod
                    for i in range(length):
                        value = poly[i]
                        if value:
                            new_poly[i + shift] = (
                                new_poly[i + shift] + value * factor
                            ) % mod

                key = (new, vertices + new, new_even)
                current = next_dp.get(key)
                if current is None:
                    next_dp[key] = new_poly
                else:
                    if len(current) < len(new_poly):
                        current.extend([0] * (len(new_poly) - len(current)))
                    for i, value in enumerate(new_poly):
                        if value:
                            current[i] = (current[i] + value) % mod

        dp = next_dp
        if not dp:
            break

    result = []
    for edges in range(n - 1, max_edges + 1):
        total = 0
        for exponent in range(edges, max_edges + 1):
            value = binomial_answer[exponent]
            if value:
                total = (total + value * choose[exponent][edges]) % mod
        result.append(str(total))

    sys.stdout.write(" ".join(result))


if __name__ == "__main__":
    main()
